async def act(page):
    import asyncio

    # Start from current page state. No knowledge_base functions are used because none are applicable for
    # Magento Admin UI interactions here.

    # Helper utilities
    async def try_click_button_by_pred(predicate):
        try:
            await page.get_by_role('button', name=predicate).first.click()
            return True
        except Exception:
            return False

    async def try_select_combobox(possible_names, option_labels=None, option_values=None):
        option_labels = option_labels or []
        option_values = option_values or []
        for name in possible_names:
            try:
                comb = page.get_by_role('combobox', name=name)
            except Exception:
                continue
            # try labels first
            for lbl in option_labels:
                try:
                    await comb.select_option(label=lbl)
                    return True
                except Exception:
                    pass
            for val in option_values:
                try:
                    await comb.select_option(value=val)
                    return True
                except Exception:
                    pass
        return False

    async def try_fill_textbox(possible_names, value):
        for name in possible_names:
            try:
                await page.get_by_role('textbox', name=name).fill(value)
                return True
            except Exception:
                pass
        return False

    # 1) Close blocking popup if present (red ×)
    try:
        await try_click_button_by_pred(lambda n: n and (('×' in n) or ('close' in n.lower()) or n.strip().lower() == 'x'))
    except Exception:
        pass
    await asyncio.sleep(0.3)

    # 2) Select all Customer Groups so rule applies to all customers
    try:
        cust_lb = page.get_by_role('listbox', name='Customer Groups *')
        await cust_lb.select_option([
            {'label': 'NOT LOGGED IN'},
            {'label': 'General'},
            {'label': 'Wholesale'},
            {'label': 'VIP Member'},
            {'label': 'Private Sales Member'},
        ])
    except Exception:
        # fallback: try name without asterisk
        try:
            cust_lb = page.get_by_role('listbox', name='Customer Groups')
            await cust_lb.select_option([
                {'label': 'NOT LOGGED IN'},
                {'label': 'General'},
                {'label': 'Wholesale'},
                {'label': 'VIP Member'},
                {'label': 'Private Sales Member'},
            ])
        except Exception:
            # proceed even if unable to set programmatically
            pass
    await asyncio.sleep(0.2)

    # 3) Open the Actions tab (link whose name contains 'Actions')
    try:
        await page.get_by_role('link', name=lambda n: n and 'actions' in n.lower()).click()
        await page.wait_for_load_state('networkidle')
        await asyncio.sleep(0.3)
    except Exception:
        # If we cannot open Actions, stop because we cannot reliably set Apply/Discount
        return

    # 4) Set the Apply/Action to a fixed cart discount
    await try_select_combobox(
        possible_names=['Apply', 'Action', 'Simple Action'],
        option_labels=['Fixed amount discount for whole cart', 'Fixed amount discount', 'Fixed Amount'],
        option_values=['cart_fixed', 'fixed', 'by_fixed']
    )
    await asyncio.sleep(0.15)

    # 5) Fill Discount Amount = 10
    await try_fill_textbox(['Discount Amount', 'Discount amount', 'Discount Amount (Fixed)'], '10')
    await asyncio.sleep(0.15)

    # 6) Save the rule (last action - will navigate away)
    try:
        await page.get_by_role('button', name='Save').click()
    except Exception:
        try:
            await page.get_by_role('button', name='Save Rule').click()
        except Exception:
            try:
                await page.get_by_role('button', name='Save and Continue Edit').click()
            except Exception:
                try:
                    await page.get_by_role('button', name=lambda n: n and 'save' in n.lower()).first.click()
                except Exception:
                    pass

    await asyncio.sleep(1)

